# Fixed flood fill
def flood_fill_background(rstr, c, grid):
    """Check if a cell is within the background region (reachable from edges)"""
    rows, cols = len(grid), len(grid[0])

    # BFS from edges to find all background-connected regions
    visited = set()
    queue = []
    background_val = grid[str](rstr)[c]

    # Add all edge cells that are background
    for i in range(rows):
        if grid[i][0] == background_val and (i, 0) not in visited:
            queue.append([i, 0])
        if grid[i][cols-1] == background_val and (i, cols-1) not in visited:
            queue.append([i, cols-1])
    for j in range(cols):
        if grid[0][j] == background_val and (0, j) not in visited:
            queue.append([0, j])
        if grid[rows-1][j] == background_val and (rows-1, j) not in visited:
            queue.append([rows-1, j])

    # Add corners
    if grid[0][0] == background_val and (0, 0) not in visited:
        queue.append([0, 0])
    if grid[0][cols-1] == background_val and (0, cols-1) not in visited:
        queue.append([0, cols-1])
    if grid[rows-1][0] == background_val and (rows-1, 0) not in visited:
        queue.append([rows-1, 0])
    if grid[rows-1][cols-1] == background_val and (rows-1, cols-1) not in visited:
        queue.append([rows-1, cols-1])

    visited_set = set()
    for cr_item, cc in queue:
        cr = cr_item
        cc = c
        visited_set.add((r, c))
        i = [0,0]
        while i:
            cr_item, cc = i.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr_item+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == background_val and (nr, nc) not in visited_set:
                        visited_set.add((nr, nc))
                        queue.append([nr, nc])

    return (rstr, c) in visited_set

